## ===========================================================================
## SC-STEM: the experiment on the RIDGE. One script, self-contained.
##
## Does the ridge on the regression coefficients work in SC-STEM? On data
## generated by SC-STEM with the regressors of the fuel application -- for each
## location p lags of its own response, p of its own "other fuel", p of the
## response of its nearest neighbour and p of the neighbour's other fuel, with
## p = 2 (moderate collinearity) or 4 (strong, the application) -- the
## experiment runs the procedure of the paper and of the application:
##
##   1. at lambda = 0, the grid of (K, phi) and the two-step selection of
##      SCSTEM_Select() on the BIC: K, phi and the partition;
##   2. on that partition, held fixed, one fit for every lambda of the grid;
##      every fit records its log-likelihood and its effective number of
##      parameters, so that the analysis can let any information criterion
##      choose lambda (AIC, AICc, GCV, HQ, KIC, BIC, EBIC; the paper uses the
##      AIC);
##
## and compares the fit at the lambda each criterion chooses with the MLE
## (lambda = 0) against three references that only a simulation has:
##
##   the TRUTH            the true coefficients of every regime: the error of
##                        every location's coefficients is that of the regime
##                        it was assigned to against those of its true regime,
##                        so that the comparison holds for any number of
##                        regimes selected;
##   the ORACLE PARTITION the true regimes, held fixed, and the same path in
##                        lambda: what the ridge does to the coefficients apart
##                        from what the partition does;
##   the ORACLE LAMBDA    on either path, the lambda with the smallest error
##                        against the truth, in hindsight: the best a ridge can
##                        do, the benchmark for the lambda a criterion picks.
##
## Interpolation. Before the fits, some values of the response are blanked: 5%
## of the cells at random (isolated holes, the kriging from the other locations
## of the regime is available) and every 20th week at every location (nothing
## observed in that week: the prediction rests on x'beta and the latent
## process). Every fit predicts them with SCSTEM_Complete(), and the error
## against the blanked values is recorded for the two kinds of hole. The lags
## of a blanked cell keep their true values (in an application they would be
## completed first); this helps every estimator alike.
##
## The ridge "works" where its error is below that of the MLE: the variance it
## removes exceeds the squared bias it adds. The design makes that happen where
## it should (few locations per regime, short series, collinear lags) and checks
## that it does no harm where it should not (more locations, longer series).
## Theory (the proposition on the ridge in Section 2 of the paper): for a small
## enough lambda the ridge is never worse, for any linear combination of the
## coefficients, interpolated values included, at given variance parameters;
## the experiment measures how much it gains, and how well each criterion finds
## such a lambda.
##
##     Rscript run-ridge-experiment.R --mode=smoke     one tiny replication, to check
##     Rscript run-ridge-experiment.R --cores=6        the experiment
##     Rscript run-ridge-experiment.R --mode=analyse   the tables, from what is done
##
## Results: one file per replication in <here>/ridge-experiment/reps/ (a run
## resumes where it stopped), the tables in <here>/ridge-experiment/.
## This is part of the REPLICATION MATERIAL of the paper, not of the Stem
## package. The comments of the results go to the supplementary material on
## the SC-STEM algorithm.
## ===========================================================================


## ---------------------------------------------------------------------------
## Where this script is; the settings, overridable with --name=value
## ---------------------------------------------------------------------------
RX_HERE <- local({
  a <- commandArgs(trailingOnly = FALSE); m <- grep("^--file=", a, value = TRUE)
  f <- if (length(m)) normalizePath(sub("^--file=", "", m[1]), winslash = "/") else NULL
  if (is.null(f)) for (i in rev(seq_len(sys.nframe()))) {
    of <- sys.frame(i)$ofile
    if (!is.null(of)) { f <- normalizePath(of, winslash = "/"); break }
  }
  if (is.null(f)) normalizePath(getwd(), winslash = "/") else dirname(f)
})
rx_config <- function(defaults, args = commandArgs(trailingOnly = TRUE)) {
  for (a in grep("^--[^=]+=.", args, value = TRUE)) {
    nm <- gsub("-", "_", sub("^--([^=]+)=.*$", "\\1", a))
    if (!nm %in% names(defaults)) stop("unknown option --", nm, call. = FALSE)
    parts <- trimws(strsplit(sub("^--[^=]+=", "", a), ",", fixed = TRUE)[[1]])
    d <- defaults[[nm]]
    defaults[[nm]] <- if (is.integer(d)) as.integer(parts) else if (is.numeric(d)) as.numeric(parts) else parts
  }
  defaults
}

CFG <- rx_config(list(
  mode     = "run",                         # "run", "smoke" or "analyse"
  n        = c(40L, 100L),                  # locations (three regimes)
  TN       = c(120L, 230L),                 # weeks
  level    = c("moderate", "strong"),      # collinearity of the lags (RX_LEVELS)
  nrep     = 50L,                           # replications per cell
  ## the ridge grid (relative scale of the package)
  lambdas  = c(0, 0.003, 0.01, 0.02, 0.03, 0.05, 0.1, 0.2, 0.3, 1),
  holes    = 0.05,                          # share of the cells blanked at random
  week_every = 20L,                         # every k-th week blanked at every location
  K_grid   = 1:3,
  phi_grid = c(0, 0.025, 0.05, 0.1, 0.2, 0.5, 1),
  phi_ref  = 0.05,                          # the penalty of the fit read at the true K
  m        = 5L,                            # the smallest regime
  knn      = 5L,
  cores    = max(1L, parallel::detectCores() - 2L),
  out      = file.path(RX_HERE, "ridge-experiment")
))
OUT <- normalizePath(CFG$out[1], winslash = "/", mustWork = FALSE)
dir.create(file.path(OUT, "reps"), recursive = TRUE, showWarnings = FALSE)

## Stem with SQUAREM for the ridge (989790b); installed from GitHub when the
## installed copy is another commit.
RX_STEM_REF <- "PaoloMaranzano/Stem@989790bf0d6d321de2cc1d3599ffb397e7db4dc8"
rx_stem <- function() {
  sha <- sub("^.*@", "", RX_STEM_REF)
  ok <- function() nzchar(system.file(package = "Stem")) &&
    identical(utils::packageDescription("Stem")$RemoteSha, sha)
  if (!ok()) {
    if (!requireNamespace("remotes", quietly = TRUE))
      utils::install.packages("remotes", repos = "https://cloud.r-project.org")
    remotes::install_github(RX_STEM_REF, upgrade = "never", force = TRUE, quiet = TRUE)
    if (!ok()) stop("Stem could not be installed at ", RX_STEM_REF, call. = FALSE)
  }
}


## ---------------------------------------------------------------------------
## The data-generating process
## ---------------------------------------------------------------------------
## Three regimes of the reference geometry of the simulation study: centres at
## the vertices of a triangle of side 2 omega (omega = 0.7), within-regime
## coordinate variance 0.4 + 2/3 - 2 omega^2 / 3. Every location i has a
## response z (the price of one fuel) and an "other fuel" o; its neighbour n is
## the nearest location. For i in regime k, with p lags per block,
##
##   z_it = sum_l [ b_kl z_i,t-l + c_kl o_i,t-l + d_kl z_n,t-l + e_kl o_n,t-l ]
##          + y^(k)_t + eps_it,
##   o_it = 0.6 o_i,t-1 + 0.2 o_i,t-2 + 0.3 c_t + rho eps_it + sqrt(1 - rho^2) u_it,
##
## y^(k) the latent AR(1) of the regime (G = 0.5, Sigmaeta = 0.1, independent
## across regimes), eps the spatial error of the regime (nugget 0.2, partial
## sill 0.2, practical range 1), c_t a shock common to every o, and rho the
## correlation between the shocks of the two fuels of a location. Every series
## is then centred on its own mean, as the relative prices of the application
## are. Two levels of collinearity of the lags:
##
##   moderate  p = 2 lags per block (8 lags),  rho = 0.5
##   strong    p = 4 lags per block (16 lags), rho = 0.9: the multi-product
##             model of the application, the two fuels of a pump moving together
##
## The coefficients decay with the lag; the regimes differ in their strength
## (scale 1, 0.5 and 1.1). Checks on the true regimes with 10% of the cells
## blanked (scratch, 2026-10-09: ridge-ic-check.R, 10 replications per cell)
## found the best lambda between 0.01 and 0.05, with the RMSE of the
## coefficients 4-6% below that of the MLE at the moderate level and 19-34%
## below at the strong level; the AIC came close to that lambda, the BIC
## shrank too much; the interpolation of the blanked cells changed by less
## than 0.1% at the lambda of the AIC.
RX_LEVELS <- list(moderate = list(p = 2L, rho = 0.5), strong = list(p = 4L, rho = 0.9))
RX_B <- list(own = c(0.35, 0.10, 0.04, 0.01), oth = c(0.10, 0.05, 0.02, 0), nb = c(0.08, 0.03, 0, 0),
             nbo = c(0.05, 0.02, 0, 0))
RX_SCALE <- c(1, 0.5, 1.1)

## the true lag coefficients, regimes x lags, named as the covariates
rx_truth <- function(p) {
  t(sapply(seq_along(RX_SCALE), function(k) {
    v <- lapply(names(RX_B), function(b)
      stats::setNames(RX_SCALE[k] * RX_B[[b]][seq_len(p)], paste0(b, "_l", seq_len(p))))
    unlist(v)
  }))
}

rx_draw <- function(n, TN, level, seed) {
  set.seed(seed)
  p <- RX_LEVELS[[level]]$p; rho <- RX_LEVELS[[level]]$rho
  K <- 3L; omega <- 0.7
  g <- rep(seq_len(K), times = c(n %/% K + (seq_len(K) <= n %% K)))
  r <- 2 * omega / sqrt(3); ang <- c(90, 210, 330) * pi / 180
  nu <- 0.4 + 2 / 3 - 2 * omega^2 / 3
  co <- cbind(x = r * cos(ang)[g] + stats::rnorm(n, sd = sqrt(nu)),
              y = r * sin(ang)[g] + stats::rnorm(n, sd = sqrt(nu)))
  h <- as.matrix(stats::dist(co)); diag(h) <- Inf
  nn <- apply(h, 1, which.min); diag(h) <- 0
  burn <- 200L; Tt <- TN + burn + p
  L <- lapply(seq_len(K), function(k) { i <- which(g == k)
    t(chol(0.2 * exp(-3 * h[i, i]) + diag(0.2, length(i)))) })
  ylat <- sapply(seq_len(K), function(k) as.numeric(stats::filter(stats::rnorm(Tt, sd = sqrt(0.1)), 0.5, method = "recursive")))
  cc <- stats::rnorm(Tt)
  TR <- rx_truth(p)
  cf <- function(k, b) TR[k, paste0(b, "_l", seq_len(p))]
  z <- o <- matrix(0, Tt, n)
  for (t in (p + 1):Tt) {
    eps <- numeric(n); for (k in seq_len(K)) { i <- which(g == k); eps[i] <- as.numeric(L[[k]] %*% stats::rnorm(length(i))) }
    o[t, ] <- 0.6 * o[t - 1, ] + 0.2 * o[t - 2, ] + 0.3 * cc[t] + rho * eps + sqrt(1 - rho^2) * stats::rnorm(n, sd = sqrt(0.4))
    zz <- numeric(n)
    for (k in seq_len(K)) { i <- which(g == k); lg <- t - seq_len(p)
      zz[i] <- ylat[t, k] + eps[i] +
        colSums(cf(k, "own") * z[lg, i, drop = FALSE]) + colSums(cf(k, "oth") * o[lg, i, drop = FALSE]) +
        colSums(cf(k, "nb") * z[lg, nn[i], drop = FALSE]) + colSums(cf(k, "nbo") * o[lg, nn[i], drop = FALSE]) }
    z[t, ] <- zz
  }
  keep <- (burn + p + 1L):Tt
  z <- sweep(z, 2, colMeans(z[keep, ])); o <- sweep(o, 2, colMeans(o[keep, ]))   # centred on the location mean
  lagm <- function(M, j, nm) { m <- sapply(seq_len(p), function(l) M[keep - l, j]); colnames(m) <- paste0(nm, "_l", seq_len(p)); m }
  covs <- lapply(seq_len(n), function(i) cbind(intercept = 1, lagm(z, i, "own"), lagm(o, i, "oth"),
                                               lagm(z, nn[i], "nb"), lagm(o, nn[i], "nbo")))
  list(z = z[keep, ], X = do.call(rbind, covs), coords = co, labels = g, truth = TR)
}


## the STEM_Model of a draw, started at least squares
rx_model <- function(dr) {
  ok <- !is.na(as.vector(dr$z))                              # starting values from the observed cells
  ols <- stats::lm.fit(dr$X[ok, , drop = FALSE], as.vector(dr$z)[ok]); s2 <- stats::var(ols$residuals)
  Stem::STEM_Model(z = dr$z, covariates = dr$X, coordinates = dr$coords,
                   phi = list(beta = matrix(ols$coefficients, ncol = 1), sigma2eps = 0.6 * s2, sigma2omega = 0.4 * s2,
                              theta = 1 / stats::median(stats::dist(dr$coords)), G = matrix(0.5, 1, 1),
                              Sigmaeta = matrix(0.2 * s2, 1, 1), m0 = as.matrix(0), C0 = as.matrix(1)),
                   A = matrix(1, ncol(dr$z), 1))
}

## the estimated regimes relabelled on the true ones (the permutation of
## largest overlap)
rx_align <- function(est, truth, K = 3L) {
  perms <- function(v) if (length(v) <= 1) list(v) else do.call(c, lapply(seq_along(v), function(i)
    lapply(perms(v[-i]), function(p) c(v[i], p))))
  best <- NULL; score <- -1
  for (p in perms(seq_len(K))) { s <- sum(p[est] == truth); if (s > score) { score <- s; best <- p } }
  best
}
rx_ari <- function(a, b) {
  tab <- table(a, b); n <- sum(tab); c2 <- function(v) sum(v * (v - 1) / 2)
  sij <- c2(as.vector(tab)); si <- c2(rowSums(tab)); sj <- c2(colSums(tab)); tot <- n * (n - 1) / 2
  e <- si * sj / tot; mx <- (si + sj) / 2; if (isTRUE(all.equal(mx, e))) 1 else (sij - e) / (mx - e)
}

## the lag coefficients of a fit, by true regime, against the truth
rx_coefs <- function(fit, labels, truth) {
  if (is.null(fit) || is.null(fit$phi_hat)) return(NULL)
  K <- nrow(fit$phi_hat)
  if (K != 3L) return(NULL)
  map <- rx_align(fit$group, labels)                       # estimated regime e -> true regime map[e]
  out <- lapply(seq_len(K), function(e) {
    b <- fit$phi_hat[e, paste0("beta", seq_len(ncol(truth)) + 1L)]
    data.frame(regime = map[e], coef = colnames(truth), estimate = unname(b), truth = unname(truth[map[e], ]))
  })
  do.call(rbind, out)
}


## ---------------------------------------------------------------------------
## One replication: every estimator and reference
## ---------------------------------------------------------------------------
rx_one <- function(task, cfg) {
  f <- file.path(cfg$out, "reps", sprintf("n%d_T%d_%s_rep%03d.rds", task$n, task$TN, task$level, task$rep))
  if (file.exists(f)) return(invisible(NULL))
  t0 <- proc.time()[["elapsed"]]
  dr <- rx_draw(task$n, task$TN, task$level, seed = 1000L * task$rep + task$n + task$TN + 7L * match(task$level, names(RX_LEVELS)))
  mod <- rx_model(dr)
  pen <- seq_len(ncol(dr$truth)) + 1L                      # the lags; not the intercept
  ctl <- Stem::STEM_control()
  ## the lambda of the BIC: the pooled model over the grid
  bic <- vapply(cfg$lambdas, function(l) {
    fx <- tryCatch(Stem::SCSTEM_Estimation(mod, K = 1, distance = "euclidean", alpha = 0, lambda = l,
                                           penalize = pen, control = ctl), error = function(e) NULL)
    if (is.null(fx)) NA_real_ else fx$info_crit[["BIC"]]
  }, 1)
  lam_bic <- cfg$lambdas[which.min(bic)]
  ## the grid and the selection, at lambda = 0 and at the lambda of the BIC
  grid <- function(l) {
    ic <- Stem::SCSTEM_Infocrit(mod, K_grid = cfg$K_grid, phi_grid = cfg$phi_grid, distance = "euclidean",
                                knn = cfg$knn, min_cluster_size = cfg$m, alpha = 0, lambda = l, penalize = pen,
                                control = ctl, verbose = FALSE)
    sel <- Stem::SCSTEM_Select(ic)
    tk <- which(ic$table$K == 3 & abs(ic$table$phi - cfg$phi_ref) < 1e-9)[1]
    ft <- if (is.na(tk)) NULL else ic$fits[[tk]]
    list(K_hat = sel$K_selected, ari_sel = rx_ari(sel$fit$group, dr$labels),
         ari_true = if (is.null(ft)) NA_real_ else rx_ari(ft$group, dr$labels), coefs = rx_coefs(ft, dr$labels, dr$truth))
  }
  est <- list(mle = grid(0))
  est$ridge_bic <- if (lam_bic == 0) est$mle else grid(lam_bic)
  ## the oracle partition: the true regimes, held fixed, every lambda of the grid
  orc <- lapply(cfg$lambdas, function(l) {
    fx <- tryCatch(Stem::SCSTEM_Estimation(mod, K = 3, phi_penalty = 0, init_partition = dr$labels, max_iter = 0,
                                           distance = "euclidean", knn = cfg$knn, min_cluster_size = cfg$m,
                                           alpha = 0, lambda = l, penalize = pen, control = ctl, verbose = FALSE),
                   error = function(e) NULL)
    if (is.null(fx)) return(NULL)
    cbind(lambda = l, rx_coefs(fx, dr$labels, dr$truth))
  })
  res <- list(task = task, lambda_bic = lam_bic, bic = bic,
              selection = data.frame(estimator = names(est), K_hat = vapply(est, `[[`, 1, "K_hat"),
                                     ari_sel = vapply(est, `[[`, 1, "ari_sel"),
                                     ari_true = vapply(est, `[[`, 1, "ari_true")),
              coefs = do.call(rbind, lapply(names(est), function(e) if (!is.null(est[[e]]$coefs))
                cbind(estimator = e, est[[e]]$coefs))),
              oracle = do.call(rbind, orc), secs = proc.time()[["elapsed"]] - t0)
  saveRDS(res, f)
  invisible(NULL)
}


## ---------------------------------------------------------------------------
## The analysis: the tables
## ---------------------------------------------------------------------------
rx_analyse <- function(out) {
  fl <- list.files(file.path(out, "reps"), "^n[0-9].*[.]rds$", full.names = TRUE)
  ne <- length(list.files(file.path(out, "reps"), "^ERROR"))
  if (ne) message(ne, " replications failed: see the ERROR files in ", file.path(out, "reps"))
  if (!length(fl)) stop("no replication done yet", call. = FALSE)
  R <- lapply(fl, readRDS)
  cell <- function(r) sprintf("%s, n = %d, T = %d", r$task$level, r$task$n, r$task$TN)
  block <- function(cf) sub("_l[0-9]+$", "", cf)
  ## 1. the coefficients of the two estimators against the truth, by block
  co <- do.call(rbind, lapply(R, function(r) if (!is.null(r$coefs)) cbind(cell = cell(r), rep = r$task$rep, r$coefs)))
  co$err <- co$estimate - co$truth; co$block <- block(co$coef)
  agg <- function(d) data.frame(bias = mean(d$err), sd = stats::sd(d$err), rmse = sqrt(mean(d$err^2)))
  t1 <- do.call(rbind, lapply(split(co, list(co$cell, co$estimator, co$block), drop = TRUE), function(d)
    cbind(cell = d$cell[1], estimator = d$estimator[1], block = d$block[1], agg(d))))
  ## the share of replications where the ridge beats the MLE (RMSE over the lags)
  rr <- stats::aggregate(err ~ cell + rep + estimator, data = co, FUN = function(e) sqrt(mean(e^2)))
  w <- stats::reshape(rr, idvar = c("cell", "rep"), timevar = "estimator", direction = "wide")
  beat <- if (all(c("err.mle", "err.ridge_bic") %in% names(w)))
    stats::aggregate(cbind(ridge_better = err.ridge_bic < err.mle - 1e-12, ridge_same = abs(err.ridge_bic - err.mle) <= 1e-12) ~ cell,
                     data = w, FUN = mean) else NULL
  ## 2. the oracle partition: RMSE against lambda, and the oracle lambda
  oc <- do.call(rbind, lapply(R, function(r) if (!is.null(r$oracle)) cbind(cell = cell(r), rep = r$task$rep, r$oracle)))
  oc$err <- oc$estimate - oc$truth; oc$block <- block(oc$coef)
  t2 <- stats::aggregate(err ~ cell + lambda + block, data = oc, FUN = function(e) sqrt(mean(e^2)))
  names(t2)[names(t2) == "err"] <- "rmse"
  tot <- stats::aggregate(err ~ cell + lambda, data = oc, FUN = function(e) sqrt(mean(e^2)))
  oracle <- do.call(rbind, lapply(split(tot, tot$cell), function(d) data.frame(
    cell = d$cell[1], oracle_lambda = d$lambda[which.min(d$err)], rmse_oracle = min(d$err),
    rmse_lambda0 = d$err[d$lambda == 0])))
  ## 3. the lambda the BIC picks, and the selection and the partition
  lb <- do.call(rbind, lapply(R, function(r) data.frame(cell = cell(r), lambda_bic = r$lambda_bic)))
  lam_tab <- as.data.frame.matrix(table(lb$cell, lb$lambda_bic))
  sel <- do.call(rbind, lapply(R, function(r) cbind(cell = cell(r), r$selection)))
  t3 <- stats::aggregate(cbind(K_correct = K_hat == 3, ari_sel, ari_true) ~ cell + estimator, data = sel, FUN = mean)
  secs <- stats::aggregate(secs ~ cell, data = do.call(rbind, lapply(R, function(r) data.frame(cell = cell(r), secs = r$secs))),
                           FUN = stats::median)
  utils::write.csv(t1, file.path(out, "coefficients_by_block.csv"), row.names = FALSE)
  utils::write.csv(t2, file.path(out, "oracle_partition_path.csv"), row.names = FALSE)
  utils::write.csv(oracle, file.path(out, "oracle_lambda.csv"), row.names = FALSE)
  utils::write.csv(cbind(cell = rownames(lam_tab), lam_tab), file.path(out, "lambda_bic.csv"), row.names = FALSE)
  utils::write.csv(t3, file.path(out, "selection_partition.csv"), row.names = FALSE)
  if (!is.null(beat)) utils::write.csv(beat, file.path(out, "ridge_beats_mle.csv"), row.names = FALSE)
  options(width = 160)
  cat(sprintf("\n%d replications\n", length(R)))
  cat("\n1. coefficients against the truth, by block\n"); print(t1, digits = 3, row.names = FALSE)
  if (!is.null(beat)) { cat("\n   share of replications where the ridge beats the MLE\n"); print(beat, digits = 3, row.names = FALSE) }
  cat("\n2. oracle partition: the oracle lambda, and the RMSE at it and at lambda = 0\n"); print(oracle, digits = 3, row.names = FALSE)
  cat("\n3. the lambda the BIC picks (counts)\n"); print(lam_tab)
  cat("\n4. selection and partition\n"); print(t3, digits = 3, row.names = FALSE)
  cat("\n5. seconds per replication (median)\n"); print(secs, row.names = FALSE)
}


